// Starting-zone quests for new race/class pairs (owner 2026-11-27, change m6-start-quests): a Night Elf Paladin etc. borrows
// the Warrior's class quests of its starting zone (table arpg_quest_proxy, generated by sql/tools/gen_start_quests.py);
// the ones given or ended by a class trainer complete on accept (they ask for a Warrior spell).
#ifndef ARPG_CHARACTER_STARTQUESTS_H
#define ARPG_CHARACTER_STARTQUESTS_H

#include <cstdint>
#include <string>

namespace Arpg::Character
{
    void InstallStartQuests();
    // Startup and .arpg reload: reads arpg_quest_proxy. Returns "startquests=<rows>".
    std::string LoadStartQuests();
    // For .arpg test questproxy: "allowed=<0|1> autocomplete=<0|1>" for a race/class and quest.
    std::string DescribeQuestProxy(uint8_t race, uint8_t cls, uint32_t questId);
}

#endif
